"""Build a readable model card and JSON summary from observed run artifacts."""
import csv,hashlib,json,re
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]; R=ROOT/'results'; M=ROOT/'models'
def readj(p):return json.loads(p.read_text(encoding='utf-8'))
def metrics(name):return readj(R/f'{name}_metrics.json')
def history(name):
    rows=list(csv.DictReader(open(R/f'{name}_history.csv',newline='',encoding='utf-8')))
    best=min(rows,key=lambda x:float(x['val_loss']))
    return {'epochs_run':len(rows),'best_epoch':int(best['epoch']),'best_val_loss':float(best['val_loss']),'best_val_accuracy':float(best['val_accuracy'])}
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def main():
    cfg=readj(R/'run_config.json');audit=readj(R/'dataset_audit.json');clean=json.loads((ROOT/'results'/'leakage_removals.json').read_text())
    runtime=readj(R/'runtime_compatibility.json');latency=readj(R/'latency_benchmark.json')
    final_source_sha=sha(ROOT/'ml'/'train.py')
    baseline_code_id=re.search(r"BASELINE_CODE_ID = '([0-9a-f]{64})'",(ROOT/'ml'/'train.py').read_text()).group(1)
    for meta_path in M.glob('*.meta.json'):
        meta=readj(meta_path);meta['final_package_train_source_sha256']=final_source_sha;meta['baseline_checkpoint_code_id']=baseline_code_id
        meta_path.write_text(json.dumps(meta,indent=2),encoding='utf-8')
    (R/'code_provenance.json').write_text(json.dumps({'final_train_py_sha256':final_source_sha,'baseline_checkpoint_code_id':baseline_code_id,'baseline_checkpoint_signature':readj(M/'baseline_aug_1.meta.json')['signature'],'sota_aug_checkpoint_signature':readj(M/'mobilenetv4_aug_1.meta.json')['signature'],'sota_noaug_checkpoint_signature':readj(M/'mobilenetv4_aug_0.meta.json')['signature'],'note':'The baseline completed before the frozen-feature SOTA speed optimization and its checkpoint signature retains the original source code ID. SOTA checkpoint signatures were recorded at fit time and cover the training-source hash plus dataset, seed, schedule, augmentation arm, and pretrained-weight hash. This final source hash identifies the packaged train.py after export-parity additions; the fitting protocol is unchanged.'},indent=2),encoding='utf-8')
    names=['baseline_aug_1','mobilenetv4_aug_1','mobilenetv4_aug_0']
    cards={}
    for n in names:
        onnx_name='baseline.onnx' if n=='baseline_aug_1' else ('sota.onnx' if n=='mobilenetv4_aug_1' else None)
        cards[n]={'training':history(n),'test_metrics':metrics(n),'checkpoint':{'path':str((M/f'{n}.pt').relative_to(ROOT)),'sha256':sha(M/f'{n}.pt'),'signature':readj(M/f'{n}.meta.json')['signature']},'onnx':({'path':str((M/onnx_name).relative_to(ROOT)),'sha256':sha(M/onnx_name),'bytes':(M/onnx_name).stat().st_size} if onnx_name else None)}
    summary={'title':'ObjectLab: household object classification','task':'4-class image classification with class-specific Grad-CAM heatmaps','classes':cfg['class_order'],'dataset':{'fingerprint_sha256':(R/'dataset_fingerprint.txt').read_text().strip(),'counts':audit['counts'],'total':audit['image_count'],'invalid_images':len(audit['invalid_images']),'cleaning':clean},'training_config':cfg,'code_provenance':readj(R/'code_provenance.json'),'models':cards,'onnx_contract':{'input_name':'images','input_dtype':'float32','input_shape':'[N,3,224,224] RGB pixels in [0,1]','outputs':{'probabilities':'float32 [N,4] in class order','heatmaps':'float32 [N,4,H,W], per-class positive Grad-CAM normalized to [0,1]'},'normalization':'ImageNet mean/std is applied inside MobileNetV4 ONNX; scratch CNN consumes RGB [0,1].','heatmap_shapes':{'baseline':[4,28,28],'sota':[4,7,7]}},'onnx_runtime_validation':runtime,'latency_benchmark':latency,'historical_a1_reference':{'baseline_cnn_test_accuracy':0.3667,'macro_f1_approx':0.32,'test_images':60,'note':'Original assignment result on its original split; the user later expanded all splits. It is not a metric for these retrained checkpoints.'},'qualitative_examples':'results/qualitative_cam_examples.png','limitations':['Single fixed split and seed; results do not establish performance across new sources or capture conditions.','A1 TensorFlow checkpoint was not provided, so the scratch model is a PyTorch architecture-level retraining, not the original A1 weights.','The MobileNetV4 augmentation bank contains four seeded transforms per training image; each epoch samples one view per image.']}
    (R/'model_card.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
    lines=['# ObjectLab model card','',f"Dataset fingerprint: `{summary['dataset']['fingerprint_sha256']}`",f"Final training source SHA-256: `{final_source_sha}`",f"Baseline checkpoint code ID: `{baseline_code_id}` (the baseline run completed before the SOTA feature-cache refactor). Checkpoint signatures and provenance are in `results/code_provenance.json`.",'',f"Class order: {', '.join(summary['classes'])}.",'',f"Split counts: train {sum(audit['counts']['train'].values())}, validation {sum(audit['counts']['val'].values())}, test {sum(audit['counts']['test'].values())}; {audit['image_count']} valid images.",'',f"Data review removed {clean['removed_nonpriority_cross_split_copies']} visually confirmed cross-split duplicate copies and {clean['removed_same_split_exact_duplicates']} byte-identical same-split duplicate. Test images were preserved.",'','## Results','', '| Model | Epochs / best epoch | Test accuracy | Macro precision | Macro recall | Macro F1 |','|---|---:|---:|---:|---:|---:|']
    for n,label in [('baseline_aug_1','Scratch CNN (A1 architecture retraining)'),('mobilenetv4_aug_1','MobileNetV4 (augmentation bank)'),('mobilenetv4_aug_0','MobileNetV4 (no train augmentation)')]:
        h=cards[n]['training'];m=cards[n]['test_metrics'];lines.append(f"| {label} | {h['epochs_run']} / {h['best_epoch']} | {m['accuracy']:.4f} | {m['macro_precision']:.4f} | {m['macro_recall']:.4f} | {m['macro_f1']:.4f} |")
    lines+=['','The MobileNetV4 arms share the same ImageNet-frozen feature extractor and schedule. Augmentation ON and OFF achieved the same results on this split. The two mistakes are scissors classified as pens. Per-class metrics and confusion matrices are in `results/*_metrics.json`.','',"## Inference contract",'',f"Input `images`: {summary['onnx_contract']['input_shape']}. Outputs are `probabilities` [N,4] and `heatmaps` [N,4,H,W] with H×W 28×28 for the scratch model and 7×7 for MobileNetV4. Both models include heatmap computation in their ONNX graph.",'',f"Desktop CPU graph-only median latency (50 runs, five warmups, two intra-op threads): baseline {latency['models'][0]['median_ms']:.2f} ms; MobileNetV4 {latency['models'][1]['median_ms']:.2f} ms. See `results/latency_benchmark.json` for environment and percentiles.",'',f"ONNX Runtime 1.20.1 validated all 81 test predictions and N=1/N=2 inputs; max probability error was {runtime['models']['baseline']['max_probability_error_vs_recorded_pytorch']:.2g} for baseline and {runtime['models']['sota']['max_probability_error_vs_recorded_pytorch']:.2g} for MobileNetV4. This is desktop Python verification, not device-specific timing.",'','## Reference and limitations','',"The historical A1 CNN score (36.67% test accuracy, macro-F1 about 0.32 on its original 60-image test set) is provided for context only; the assignment dataset was later expanded. These models were trained on 461 training images, selected using 81 validation images, and evaluated on 81 held-out test images.",'',"The MobileNetV4 checkpoint uses the [timm model card](https://huggingface.co/timm/mobilenetv4_conv_small.e2400_r224_in1k) (Apache-2.0) and [paper](https://arxiv.org/abs/2404.10518). The original A1 TensorFlow weights were unavailable, so the baseline is a PyTorch architecture-level retraining.",'',"These results use one seed and one manually curated split. They describe the supplied data and do not estimate performance across new capture sources.",'']
    (ROOT/'MODEL_CARD.md').write_text('\n'.join(lines),encoding='utf-8')
    print(ROOT/'MODEL_CARD.md')
if __name__=='__main__':main()
